import type { TraceItem } from "@cloudflare/workers-types";
import type { z } from "zod";

export type WorkerIdentity =
  | { appId: string; deploymentId: string; buildId: string | null }
  | { organizationId: string; connector: string; connectorVersion: string };

export type WorkflowIdentity = {
  appId: string;
  version: string;
  workflow: string;
  // Native instance ID generated by the catalog, not the application's ID.
  instanceId: string;
};

export type WorkflowObservation = { timestamp: number } & (
  | {
      operation: "create";
      // A rejected native response cannot prove the instance was not created.
      outcome: "ok" | "unknown";
    }
  | {
      operation: "do";
      // Entry into attempt 1, before app code runs. Not a completion or a
      // provider billing total. Cached results and later attempts emit nothing.
      outcome: "started";
    }
);

export type KeyValueObservation = {
  timestamp: number;
  binding: string;
  operation: "read" | "write" | "delete" | "list";
  // Requested keys (including misses), or one list call. Errors remain attempts,
  // not a claim that the provider billed every requested operation.
  count: number;
  outcome: "ok" | "error";
};

export type ObjectObservation = {
  timestamp: number;
  binding: string;
  operation:
    | "get"
    | "head"
    | "put"
    | "delete"
    | "list"
    | "createMultipartUpload"
    | "uploadPart"
    | "complete"
    | "abort";
  // One native binding call, including bulk/empty deletes and each list page.
  // Not an object count or a claim about provider requests or billing.
  count: 1;
  // Describes promise settlement, not later body consumption. A missing get/head
  // and an unmet get/put condition are distinct from rejected native calls.
  outcome: "ok" | "not_found" | "precondition_failed" | "error";
};

export type DatabaseObservation = {
  timestamp: number;
  binding: string;
  // The existing facade routes run() through all(). No SQL classification.
  operation: "all" | "first" | "raw" | "batch" | "exec";
  // One event per native _send, before first/raw/exec project away metadata.
  // Outcome describes that native response, not subsequent JS projection errors.
  outcome: "ok" | "error" | "unknown";
  statements: number;
  // Sum each returned statement once. A missing counter or response makes that
  // entire dimension unknown. Native retry totals are never multiplied.
  rowsRead: number | null;
  rowsWritten: number | null;
};

export interface RuntimeExtension {
  // Cloudflare parent contexts only. No sleeps/event waits, rollback handlers,
  // engine CPU or persisted-state bytes. Explicit restarts can execute do steps
  // again. Delivery runs as background work and does not gate native execution.
  // Termination, catalog resets and failed delivery can lose observations.
  workflow?: (
    event: WorkflowObservation,
    identity: WorkflowIdentity,
    binding: <Value>(name: string, schema: z.ZodType<Value>) => Value,
  ) => Promise<void>;
  // Same parent-context delivery semantics as keyValue. Handle-only multipart
  // resume and failures before native invocation produce no observation.
  object?: (
    event: ObjectObservation,
    identity: WorkerIdentity,
    binding: <Value>(name: string, schema: z.ZodType<Value>) => Value,
  ) => Promise<void>;
  database?: (
    event: DatabaseObservation,
    identity: WorkerIdentity,
    binding: <Value>(name: string, schema: z.ZodType<Value>) => Value,
  ) => Promise<void>;
  // Runs in the parent request context. KV calls do not await delivery, but
  // synchronous work in the callback still contributes to request latency.
  keyValue?: (
    event: KeyValueObservation,
    identity: WorkerIdentity,
    binding: <Value>(name: string, schema: z.ZodType<Value>) => Value,
  ) => Promise<void>;
  tail?: (
    events: TraceItem[],
    identity: WorkerIdentity,
    binding: <Value>(name: string, schema: z.ZodType<Value>) => Value,
  ) => Promise<void>;
}

// Installations may replace this module when building their runtime.
export const runtimeExtension: RuntimeExtension = {};
